package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParseException;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.BufferRecycler;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.sym.*;
import com.fasterxml.jackson.core.util.*;
import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for UTF8StreamJsonParser._parseNumber.
 * Note: Since _parseNumber is protected, this test class must be in the same package
 * or we must use a subclass to expose it for testing.
 */
public class UTF8StreamJsonParser__parseNumber_TriageGen0Test {

    private TestableParser parser;

    // Subclass to expose protected method _parseNumber
    private static class TestableParser extends UTF8StreamJsonParser {
        public TestableParser(IOContext ctxt, int features, InputStream in, ObjectCodec codec, 
                             BytesToNameCanonicalizer sym, byte[] inputBuffer, int start, int end, boolean bufferRecyclable) {
            super(ctxt, features, in, codec, sym, inputBuffer, start, end, bufferRecyclable);
        }

        @Override
        public JsonToken _parseNumber(int c) throws IOException, JsonParseException {
            return super._parseNumber(c);
        }
    }

    private static final int INT_MINUS = '-';
    private static final int INT_0 = '0';
    private static final int INT_9 = '9';

    @Before
    public void setUp() {
        // Setup is handled per test case because the constructor requires specific buffer states
    }

    private TestableParser createParser(String json) throws IOException {
        byte[] bytes = json.getBytes(StandardCharsets.UTF_8);
        return new TestableParser(
                IOContext.bootstrap(),
                0,
                new ByteArrayInputStream(bytes),
                null,
                null,
                bytes,
                0,
                bytes.length,
                true
        );
    }

    @Test
    public void testParsePositiveInteger() throws IOException, JsonParseException {
        TestableParser parser = createParser("123,");
        // The first char passed to _parseNumber is '1'
        JsonToken token = parser._parseNumber('1');
        assertEquals(JsonToken.VALUE_NUMBER_INT, token);
        assertEquals("123", parser.getValueAsString());
    }

    @Test
    public void testParseNegativeInteger() throws IOException, JsonParseException {
        TestableParser parser = createParser("-123,");
        // The first char passed is '-'
        JsonToken token = parser._parseNumber('-');
        assertEquals(JsonToken.VALUE_NUMBER_INT, token);
        assertEquals("-123", parser.getValueAsString());
    }

    @Test(expected = JsonParseException.class)
    public void testParseInvalidNegativeNumber() throws IOException, JsonParseException {
        // '-' followed by non-digit
        TestableParser parser = createParser("-a");
        parser._parseNumber('-');
    }

    @Test
    public void testParseZero() throws IOException, JsonParseException {
        TestableParser parser = createParser("0,");
        JsonToken token = parser._parseNumber('0');
        assertEquals(JsonToken.VALUE_NUMBER_INT, token);
        assertEquals("0", parser.getValueAsString());
    }

    @Test(expected = JsonParseException.class)
    public void testParseLeadingZeroError() throws IOException, JsonParseException {
        // "01" is invalid in strict JSON
        TestableParser parser = createParser("01,");
        parser._parseNumber('0');
    }

    @Test
    public void testParseFloatWithDot() throws IOException, JsonParseException {
        TestableParser parser = createParser("12.34,");
        JsonToken token = parser._parseNumber('1');
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, token);
        assertEquals("12.34", parser.getValueAsString());
    }

    @Test
    public void testParseScientificNotationE() throws IOException, JsonParseException {
        TestableParser parser = createParser("1e10,");
        JsonToken token = parser._parseNumber('1');
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, token);
        assertEquals("1e10", parser.getValueAsString());
    }

    @Test
    public void testParseScientificNotationSmallE() throws IOException, JsonParseException {
        TestableParser parser = createParser("1E10,");
        JsonToken token = parser._parseNumber('1');
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, token);
        assertEquals("1E10", parser.getValueAsString());
    }

    @Test
    public void testParseLargeNumberCrossingBufferBoundary() throws IOException, JsonParseException {
        // Create a very long number to trigger _parserNumber2 (buffer boundary logic)
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 500; i++) {
            sb.append('1');
        }
        sb.append(',');
        TestableParser parser = createParser(sb.toString());

        JsonToken token = parser._parseNumber('1');
        assertEquals(JsonToken.VALUE_NUMBER_INT, token);
        // Check if length is correct (though value is huge)
        assertEquals(500, parser.getTextLength());
    }

    @Test
    public void testParseNegativeZero() throws IOException, JsonParseException {
        // Technically -0 is a number in some parsers, checking logic flow
        TestableParser parser = createParser("-0,");
        JsonToken token = parser._parseNumber('-');
        assertEquals(JsonToken.VALUE_NUMBER_INT, token);
        assertEquals("-0", parser.getValueAsString());
    }

    @Test
    public void testParseNumberWithTrailingNonDigit() throws IOException, JsonParseException {
        // Testing the --_inputPtr logic and the break in while loop
        TestableParser parser = createParser("123abc");
        JsonToken token = parser._parseNumber('1');
        assertEquals(JsonToken.VALUE_NUMBER_INT, token);
        assertEquals("123", parser.getValueAsString());
    }
}
